package clinical

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// Grant 由内部使用者为一名接收方建立针对某患者的整类读取授权。
//
// 这是 [Store.GrantSelective] 的整类形式：范围由明确的“就诊 + 类别
// （诊断/医嘱）”组合构成，覆盖各就诊+类别下的全部已生效记录（含授权
// 建立后才生效的记录）。不允许空范围，每个就诊都必须属于该患者
// （跨患者就诊会被拒绝），类别必须合法。时间窗为半开区间
// [startsAt, expiresAt)：开始时刻即生效，到截止时刻立即失效；
// 开始不早于截止时间（相等也算）一律拒绝。患者档案停用后不能新建授权。
// 授权与审计事件在同一次原子落盘中保留。
func (s *Store) Grant(actor Actor, patientID ID, receiverID string, scopes []Scope, startsAt, expiresAt time.Time) (Authorization, error) {
	return s.GrantSelective(actor, patientID, receiverID, scopes, nil, startsAt, expiresAt)
}

// GrantSelective 由内部使用者为一名接收方建立针对某患者的读取授权，
// 整类范围（scopes）与限定记录范围（selections）可以并存，同一条授权
// 可以包含多个就诊、类别。
//
// scopes 的每项按整类授权：覆盖该就诊+类别下全部已生效记录，并自然
// 包含授权后新增生效的记录；selections 的每项明确选出一条已生效记录，
// 被选记录更正后授权覆盖它的当前版本，但同一就诊同一类别的其他记录、
// 后来新增并生效的记录都不会自动进入限定范围。重复选择同一记录只算一次。
//
// scopes 与 selections 不能同时为空：空选择不代表整类授权。scope 中的
// 就诊必须存在且属于该患者，类别必须合法。每条 selection 都必须显式
// 声明记录所属的就诊与类别，且：记录不存在返回 ErrNotFound；记录属于
// 其他患者返回 ErrMismatchedPatient；空选择、空白标识、选择了尚未生效
// 的草稿、记录与声明的就诊或类别不符返回 ErrInvalidArgument。任一选择
// 不合法就拒绝整条授权：不保存合法部分，也不新增审计。
//
// 时间窗、停用档案与审计规则与 [Store.Grant] 相同。
func (s *Store) GrantSelective(actor Actor, patientID ID, receiverID string, scopes []Scope, selections []RecordSelection, startsAt, expiresAt time.Time) (Authorization, error) {
	if !actor.valid() || !actor.IsInternal() {
		return Authorization{}, ErrAccessDenied
	}
	if patientID == "" {
		return Authorization{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
	}
	if strings.TrimSpace(receiverID) == "" {
		return Authorization{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
	}
	if len(scopes) == 0 && len(selections) == 0 {
		return Authorization{}, fmt.Errorf("%w: authorization scope must not be empty", ErrInvalidArgument)
	}
	for _, sc := range scopes {
		if sc.EncounterID == "" {
			return Authorization{}, fmt.Errorf("%w: scope encounter id is required", ErrInvalidArgument)
		}
		if !validCategory(sc.Category) {
			return Authorization{}, fmt.Errorf("%w: scope category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
		}
	}
	for _, sel := range selections {
		if strings.TrimSpace(sel.RecordID) == "" {
			return Authorization{}, fmt.Errorf("%w: selection record id is required", ErrInvalidArgument)
		}
		if strings.TrimSpace(sel.EncounterID) == "" {
			return Authorization{}, fmt.Errorf("%w: selection encounter id is required", ErrInvalidArgument)
		}
		if !validCategory(sel.Category) {
			return Authorization{}, fmt.Errorf("%w: selection category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
		}
	}
	if !startsAt.Before(expiresAt) {
		return Authorization{}, fmt.Errorf("%w: starts-at must be strictly before expires-at", ErrInvalidArgument)
	}

	var result Authorization
	err := s.mutate(func(snap *snapshot) error {
		if _, err := requireActivePatient(snap, patientID); err != nil {
			return err
		}

		// 去重并逐项校验整类范围：引用的就诊必须存在且属于该患者。
		seenScope := map[Scope]bool{}
		cleanedScopes := make([]Scope, 0, len(scopes))
		for _, sc := range scopes {
			if _, err := requireEncounter(snap, patientID, sc.EncounterID); err != nil {
				return err
			}
			if seenScope[sc] {
				continue
			}
			seenScope[sc] = true
			cleanedScopes = append(cleanedScopes, sc)
		}
		sort.Slice(cleanedScopes, func(i, j int) bool {
			if cleanedScopes[i].EncounterID != cleanedScopes[j].EncounterID {
				return cleanedScopes[i].EncounterID < cleanedScopes[j].EncounterID
			}
			return cleanedScopes[i].Category < cleanedScopes[j].Category
		})

		// 逐项校验限定范围：就诊必须属于该患者；记录必须存在、属于该患者、
		// 已生效，且实际就诊与类别与声明一致。任一不合法即整体拒绝。
		seenRecord := map[ID]bool{}
		cleanedSelections := make([]RecordSelection, 0, len(selections))
		for _, sel := range selections {
			if _, err := requireEncounter(snap, patientID, sel.EncounterID); err != nil {
				return err
			}
			r := snap.Records[sel.RecordID]
			if r == nil {
				return fmt.Errorf("%w: record %q", ErrNotFound, sel.RecordID)
			}
			if r.PatientID != patientID {
				return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
					ErrMismatchedPatient, sel.RecordID, r.PatientID, patientID)
			}
			if r.CurrentVersionID == "" {
				return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
					ErrInvalidArgument, sel.RecordID)
			}
			if r.EncounterID != sel.EncounterID || r.Category != sel.Category {
				return fmt.Errorf("%w: record %q belongs to encounter %q category %q, not declared encounter %q category %q",
					ErrInvalidArgument, sel.RecordID, r.EncounterID, r.Category, sel.EncounterID, sel.Category)
			}
			if seenRecord[sel.RecordID] {
				// 重复选择同一记录只算一次。
				continue
			}
			seenRecord[sel.RecordID] = true
			cleanedSelections = append(cleanedSelections, sel)
		}
		sort.Slice(cleanedSelections, func(i, j int) bool {
			return cleanedSelections[i].RecordID < cleanedSelections[j].RecordID
		})

		now := s.now()
		a := &Authorization{
			ID:         newID("auth"),
			PatientID:  patientID,
			ReceiverID: receiverID,
			Scopes:     cleanedScopes,
			Selections: cleanedSelections,
			StartsAt:   startsAt.UTC(),
			ExpiresAt:  expiresAt.UTC(),
			CreatedAt:  now,
		}
		snap.Authorizations[a.ID] = a
		s.addAudit(snap, patientID, actor, ActionGranted, "authorization", a.ID, now)
		result = *a
		return nil
	})
	return result, err
}

// Revoke 提前撤回授权。撤回在当前时间生效；此后该授权不再覆盖任何读取。
// 重复撤回返回成功且不产生额外变化（不新增审计事件），与“停用”语义一致。
// 撤回其他患者的授权 ID 会得到 ErrMismatchedPatient/ErrNotFound。
func (s *Store) Revoke(actor Actor, patientID, authorizationID ID) error {
	if !actor.valid() || !actor.IsInternal() {
		return ErrAccessDenied
	}
	return s.mutate(func(snap *snapshot) error {
		a := snap.Authorizations[authorizationID]
		if a == nil {
			return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
		}
		if a.PatientID != patientID {
			return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
				ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
		}
		if a.RevokedAt != nil {
			// 幂等：保持已有撤回结果，不生成额外变化或事件。
			return nil
		}
		now := s.now()
		a.RevokedAt = &now
		s.addAudit(snap, patientID, actor, ActionRevoked, "authorization", a.ID, now)
		return nil
	})
}

// GetAuthorization 返回单个授权。仅供内部使用者。
func (s *Store) GetAuthorization(actor Actor, patientID, authorizationID ID) (Authorization, error) {
	if !actor.valid() || !actor.IsInternal() {
		return Authorization{}, ErrAccessDenied
	}
	var result Authorization
	err := s.view(func(snap *snapshot) error {
		a := snap.Authorizations[authorizationID]
		if a == nil {
			return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
		}
		if a.PatientID != patientID {
			return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
				ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
		}
		result = *a
		return nil
	})
	return result, err
}

// ListAuthorizations 列出某患者（可选：某接收方）的全部授权，含已撤回者。
// 仅供内部使用者。
func (s *Store) ListAuthorizations(actor Actor, patientID ID, receiverID string) ([]Authorization, error) {
	if !actor.valid() || !actor.IsInternal() {
		return nil, ErrAccessDenied
	}
	var result []Authorization
	err := s.view(func(snap *snapshot) error {
		if _, err := requirePatient(snap, patientID); err != nil {
			return err
		}
		for _, a := range snap.Authorizations {
			if a.PatientID != patientID {
				continue
			}
			if receiverID != "" && a.ReceiverID != receiverID {
				continue
			}
			result = append(result, *a)
		}
		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
		return nil
	})
	return result, err
}

// Read 供接收方按自己的身份读取某次就诊下某个类别（诊断/医嘱）的内容。
//
// 结果是该接收方在“本次读取时间”所有当前有效授权允许记录的合集，每条记录
// 只出现一次并按记录标识稳定排序：授权必须属于该接收方与该患者、已开始、
// 未到期且未撤回；整类范围（Scope）允许该就诊+类别下的全部已生效记录
// （含授权后才生效者），限定范围（RecordSelection）仅允许明确选中的记录。
// 同一条记录被多条授权（含整类与限定重叠）允许也只出现一次；被选记录被
// 更正后读取其当前生效版本。看不到草稿、旧版本或更正原因。
//
// 若不存在任何覆盖所请求就诊+类别的有效授权（全部尚未开始、已到期或已
// 撤回），或患者档案已停用，返回 ErrAccessDenied：结果中不含任何未授权
// 记录的标识、数量或内容。撤回整类授权后，只剩其他有效授权明确允许的记录。
func (s *Store) Read(actor Actor, patientID, encounterID ID, category string) (ReadResult, error) {
	if !actor.valid() || actor.Kind != "receiver" {
		return ReadResult{}, ErrAccessDenied
	}
	if patientID == "" || encounterID == "" {
		return ReadResult{}, fmt.Errorf("%w: patient and encounter ids are required", ErrInvalidArgument)
	}
	if !validCategory(category) {
		return ReadResult{}, fmt.Errorf("%w: category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
	}

	now := s.now()
	var out ReadResult
	err := s.view(func(snap *snapshot) error {
		// 汇总当前有效的授权：哪些整类（就诊+类别）被覆盖，哪些具体记录被
		// 限定范围明确允许。不提前区分“对象不存在/属于他人”与“无授权”，
		// 统一返回拒绝，从而不向接收方泄露患者或就诊是否存在。
		wholeCategory := false
		allowedRecords := map[ID]bool{}
		patientDeactivated := false
		if p := snap.Patients[patientID]; p != nil {
			patientDeactivated = p.Deactivated
		}
		for _, a := range snap.Authorizations {
			if a.PatientID != patientID || a.ReceiverID != actor.ID {
				continue
			}
			if !a.ActiveAt(now) {
				continue
			}
			if authorizationCovers(a, encounterID, category) {
				wholeCategory = true
			}
			for _, sel := range a.Selections {
				if sel.EncounterID == encounterID && sel.Category == category {
					allowedRecords[sel.RecordID] = true
				}
			}
		}
		if patientDeactivated || (!wholeCategory && len(allowedRecords) == 0) {
			// 无授权、未开始、已到期、已撤回或档案停用：明确拒绝，
			// 结果中不含任何受保护内容。
			return ErrAccessDenied
		}

		// 能被授权覆盖的就诊必然属于该患者（Grant 时已校验），
		// 此处再确认一次以防任何不一致状态。
		e := snap.Encounters[encounterID]
		if e == nil || e.PatientID != patientID {
			return ErrAccessDenied
		}

		out.EncounterID = encounterID
		out.Category = category
		var recs []EffectiveRecord
		for _, r := range snap.Records {
			if r.EncounterID != encounterID || r.Category != category || r.PatientID != patientID {
				continue
			}
			// 整类范围覆盖全部；限定范围只覆盖明确选中的记录。
			// 多个授权、整类与限定重叠时同一条记录只出现一次。
			if !wholeCategory && !allowedRecords[r.ID] {
				continue
			}
			if eff, ok := currentEffective(snap, r); ok {
				recs = append(recs, eff)
			}
			// 仅有草稿、尚无生效版本的记录天然不出现；
			// 限定授权选中的记录在授权后也不会退回草稿状态。
		}
		sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
		out.Records = recs
		return nil
	})
	return out, err
}

// authorizationCovers 报告授权的整类范围是否覆盖某次就诊下某个类别。
func authorizationCovers(a *Authorization, encounterID ID, category string) bool {
	for _, sc := range a.Scopes {
		if sc.EncounterID == encounterID && sc.Category == category {
			return true
		}
	}
	return false
}

// authorizationCoversRecord 报告授权本身（整类范围或限定范围）是否覆盖
// 某条具体记录：整类范围按记录的就诊+类别覆盖，限定范围只覆盖明确选中
// 的记录。其他授权不能替代该绑定授权完成覆盖。
func authorizationCoversRecord(a *Authorization, r *Record) bool {
	if authorizationCovers(a, r.EncounterID, r.Category) {
		return true
	}
	for _, sel := range a.Selections {
		if sel.RecordID == r.ID {
			return true
		}
	}
	return false
}

package clinical

import (
	"errors"
	"time"
)

// 记录类别：诊断与医嘱。
const (
	Diagnosis = "diagnosis"
	Order     = "order"
)

// 审计动作。
const (
	ActionActivated   = "activated"
	ActionCorrected   = "corrected"
	ActionGranted     = "authorization_granted"
	ActionRevoked     = "authorization_revoked"
	ActionDeactivated = "patient_deactivated"
	ActionExchanged   = "exchange_created"
	ActionReceipted   = "receipt_registered"
)

// 合成数据标记。本包只处理合成患者资料，登记时统一写入。
const SyntheticSource = "synthetic"

// 调用方身份。Internal 为内部使用者，Receiver 为接收方。
//
// 内部使用者可查看全部草稿与完整历史、建立与撤回授权、维护档案；
// 接收方只能凭有效授权读取当前生效版本。
type Actor struct {
	ID   string
	Kind string // "internal" 或 "receiver"
}

// InternalActor 构造一个内部使用者身份。
func InternalActor(id string) Actor { return Actor{ID: id, Kind: "internal"} }

// ReceiverActor 构造一个接收方身份。
func ReceiverActor(id string) Actor { return Actor{ID: id, Kind: "receiver"} }

// IsInternal 报告该身份是否为内部使用者。
func (a Actor) IsInternal() bool { return a.Kind == "internal" }

func (a Actor) valid() bool {
	if a.ID == "" {
		return false
	}
	return a.Kind == "internal" || a.Kind == "receiver"
}

// ID 是患者、就诊、记录、版本、授权与审计事件的稳定标识。
// ID 在各自类型的集合内唯一，由登记操作生成并原样返回，
// 关闭后从同一位置重新打开仍然有效。
type ID = string

// Patient 是一名合成患者的档案。
type Patient struct {
	ID          ID
	Name        string
	Source      string // 始终为 SyntheticSource
	Deactivated bool
	CreatedAt   time.Time
}

// Encounter 是患者的一次就诊。
type Encounter struct {
	ID         ID
	PatientID  ID
	OccurredAt time.Time
	CreatedAt  time.Time
}

// Version 是一条记录在某一时刻被固化的完整内容。
// 生效产生第 1 版；每次更正产生新版本并通过 PrevID 链接到上一版本。
type Version struct {
	ID        ID
	RecordID  ID
	Number    int
	Content   string
	Category  string
	CreatedAt time.Time // 生效或更正发生的时间
	PrevID    ID        // 上一版本；第 1 版为空
	Reason    string    // 更正原因；第 1 版为空
}

// Record 是一条诊断或医嘱。它在草稿与版本之间推进：
// 草稿可反复修改或删除；生效后产生不可变的当前版本，
// 此后只能通过更正产生新版本，不能被直接覆盖或删除。
type Record struct {
	ID          ID
	PatientID   ID
	EncounterID ID
	Category    string

	DraftContent string
	HasDraft     bool

	CurrentVersionID ID
	Versions         []ID // 按版本号顺序，旧到新
}

// Authorization 是内部使用者为一名接收方建立的、针对某患者的读取授权。
// 范围由两类条目组成，二者可并存、均可覆盖多条就诊与类别：
//
//   - Scopes：整类范围，覆盖某次就诊下某个类别（诊断/医嘱）的全部已生效
//     记录，含授权建立之后才生效的记录；读取时始终取记录的当前生效版本。
//   - Selections：限定范围，仅覆盖明确选出的具体记录。被选记录被更正后
//     授权覆盖它的当前版本；但同一就诊同一类别的其他记录、以及后来新增
//     并生效的记录都不会自动进入限定范围。
//
// 授权仅在 [StartsAt, ExpiresAt) 内有效。
type Authorization struct {
	ID         ID
	PatientID  ID
	ReceiverID string
	Scopes     []Scope
	// Selections 为限定范围中明确选出的记录。为空表示该授权只有整类范围；
	// 旧数据与 Grant 建立的授权该字段始终为空。
	Selections []RecordSelection
	StartsAt   time.Time
	ExpiresAt  time.Time
	RevokedAt  *time.Time // 撤回时间；nil 表示未撤回
	CreatedAt  time.Time
}

// ActiveAt 报告授权在时刻 t 是否有效：已开始、未到期、未撤回。
// 开始时刻即生效；到截止时刻立即失效（半开区间 [StartsAt, ExpiresAt)）。
func (a *Authorization) ActiveAt(t time.Time) bool {
	if a.RevokedAt != nil {
		return false
	}
	if t.Before(a.StartsAt) {
		return false
	}
	if !t.Before(a.ExpiresAt) {
		return false
	}
	return true
}

// Scope 是授权范围中的一项：某次就诊下的某个记录类别。
type Scope struct {
	EncounterID ID
	Category    string
}

// RecordSelection 是授权限定范围中的一项：明确选出某条已生效记录，
// 并声明它所属的就诊与类别。建立授权时记录必须存在、已生效、属于该
// 患者，且其实际就诊与类别必须与声明一致；同一记录在一条授权内重复
// 选择只算一次。
type RecordSelection struct {
	EncounterID ID
	Category    string
	RecordID    ID
}

// AuditEvent 是一条仅供内部使用者按患者查看的审计事件。
type AuditEvent struct {
	ID         ID
	PatientID  ID
	ActorID    string
	Action     string
	ObjectType string
	ObjectID   ID
	OccurredAt time.Time
}

// ReadResult 是接收方一次受限读取得到的内容。
type ReadResult struct {
	EncounterID ID
	Category    string
	// Records 为该就诊该类别下、当前生效且被有效授权覆盖的记录，
	// 每项只含当前生效版本的完整内容，不含草稿、旧版本或更正原因。
	Records []EffectiveRecord
}

// EffectiveRecord 是对外暴露的一条当前生效记录。
type EffectiveRecord struct {
	RecordID    ID
	VersionID   ID
	Version     int
	Content     string
	EffectiveAt time.Time
}

// 交换状态：创建后待回执，接收方登记回执后转为已接受或已拒绝。
const (
	ExchangePending  = "pending_receipt"
	ExchangeAccepted = "accepted"
	ExchangeRejected = "rejected"
)

// 回执结果：接受或拒绝打包内容。
const (
	ReceiptAccepted = "accepted"
	ReceiptRejected = "rejected"
)

// PackagedRecord 是包内固化的一条记录版本。包在创建时取各记录的当前生效
// 版本快照：此后记录被更正或新增版本都不会改写包内容。
//
// 只含核对所需的标识、版本号、生效时间与完整内容，不含患者姓名、草稿、
// 历史版本或更正原因（Version.Reason）。
type PackagedRecord struct {
	EncounterID ID
	Category    string
	RecordID    ID
	VersionID   ID
	Version     int
	EffectiveAt time.Time
	Content     string
}

// Package 是一份已固化的交换内容：只含患者与接收方标识及各记录的版本快照。
type Package struct {
	PatientID  ID
	ReceiverID string
	Records    []PackagedRecord
}

// Receipt 是接收方对一份包的回执。接受时 Reason 为空；拒绝时 Reason 必填。
type Receipt struct {
	Outcome      string
	Reason       string
	RegisteredAt time.Time
}

// Exchange 是把已授权记录打包给指定接收方的一次交换。
//
// 创建即把当时的当前版本固化进 Package 并计算摘要；状态初始为待回执。
// 请求号（RequestID）按发起的内部使用者区分，用于安全重试：同一使用者以
// 相同请求号、患者、接收方、绑定授权与记录集合重试时返回原交换。
type Exchange struct {
	ID              ID
	PatientID       ID
	ReceiverID      string
	AuthorizationID ID
	RequestID       string
	CreatorID       string // 创建交换的内部使用者标识
	Status          string // ExchangePending/Accepted/Rejected
	Digest          string // 包内容摘要，接收方回执时须原样回传
	Package         Package
	Receipt         *Receipt
	CreatedAt       time.Time
}

// 失败一律返回明确错误，不留下半条记录。
var (
	// ErrNotFound 表示引用的患者、就诊、记录、版本或授权不存在。
	ErrNotFound = errors.New("clinical: referenced object not found")
	// ErrMismatchedPatient 表示混用了属于不同患者的对象。
	ErrMismatchedPatient = errors.New("clinical: objects belong to different patients")
	// ErrInvalidArgument 表示参数本身不合法（空内容、空范围、时间窗倒置等）。
	ErrInvalidArgument = errors.New("clinical: invalid argument")
	// ErrConflict 表示乐观并发冲突：指定的版本已不再是当前版本。
	ErrConflict = errors.New("clinical: version conflict")
	// ErrDeactivated 表示患者档案已停用，该写操作不再允许。
	ErrDeactivated = errors.New("clinical: patient record is deactivated")
	// ErrActive 表示记录已有生效版本，不能按草稿方式直接覆盖或删除。
	ErrActive = errors.New("clinical: record is already effective")
	// ErrAccessDenied 表示接收方没有覆盖所请求范围的有效授权，
	// 或内部规则不允许该身份执行此操作。返回时不携带任何受保护内容。
	ErrAccessDenied = errors.New("clinical: access denied")
	// ErrClosed 表示 Store 已关闭。
	ErrClosed = errors.New("clinical: store closed")
)

